"""Tests for check-no-training-on-user-data.py. Run: python3 scripts/test_check_no_training_on_user_data.py"""

import importlib.util
import json
import tempfile
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location("check", HERE / "check-no-training-on-user-data.py")
check = importlib.util.module_from_spec(spec)
spec.loader.exec_module(check)

GOOD_MANIFEST = {"sources": [{"name": "hud-register-synth", "kind": "synthetic", "contains_user_data": False,
                              "provenance": "generated by scripts/gen_hud_pairs.py"}]}


class Tree(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.repo = Path(self.tmp.name)

    def tearDown(self):
        self.tmp.cleanup()

    def write(self, rel, text):
        p = self.repo / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text if isinstance(text, str) else json.dumps(text), encoding="utf-8")

    def problems(self):
        return check.run(self.repo)[0]

    def test_clean_tree(self):
        self.write("miniapps/assistant/src/a.ts", "export const train = 'the 8:15 to Pune'\n")
        self.assertEqual(self.problems(), [])

    def test_fine_tune_api_in_app_code_fails(self):
        self.write("miniapps/assistant/src/learn.ts", "await fetch(base + '/v1/fine_tuning/jobs', {method: 'POST'})\n")
        [p] = self.problems()
        self.assertIn("hosted fine-tune API in app code", p)

    def test_lora_in_app_code_fails(self):
        self.write("miniapps/assistant/tools/adapt.py", "from peft import LoraConfig\n")
        self.assertEqual(len(self.problems()), 1)

    def test_an_adr_marker_allows_one_line(self):
        self.write("miniapps/x.py", "from peft import LoraConfig  # no-user-data-training:allow ADR-009\n")
        self.assertEqual(self.problems(), [])

    def test_a_marker_without_an_adr_does_not(self):
        self.write("miniapps/x.py", "from peft import LoraConfig  # no-user-data-training:allow\n")
        self.assertEqual(len(self.problems()), 1)

    def test_training_code_needs_a_manifest(self):
        self.write("training/train.py", "from peft import LoraConfig\n")
        [p] = self.problems()
        self.assertIn("DATA_SOURCES.json is missing", p)

    def test_training_with_a_sound_manifest_passes(self):
        # LoRA for form on synthetic data is exactly what ANI-90 allows.
        self.write("training/train.py", "from peft import LoraConfig\n")
        self.write("training/DATA_SOURCES.json", GOOD_MANIFEST)
        self.assertEqual(self.problems(), [])

    def test_manifest_must_rule_out_user_data(self):
        self.write("training/train.py", "x = 1\n")
        self.write("training/DATA_SOURCES.json", {"sources": [
            {"name": "usage-logs", "kind": "production", "contains_user_data": True, "provenance": "app telemetry"},
            {"name": "unsaid", "kind": "curated", "provenance": "hand-written"},
        ]})
        ps = self.problems()
        self.assertTrue(any("usage-logs: kind" in p for p in ps))
        self.assertTrue(any("usage-logs: contains_user_data" in p for p in ps))
        # Leaving the field out is not the same as saying false.
        self.assertTrue(any("unsaid: contains_user_data" in p for p in ps))

    def test_training_code_may_not_read_the_memory_store(self):
        self.write("training/DATA_SOURCES.json", GOOD_MANIFEST)
        self.write("training/build_set.ts", "import {MemoryService} from '../miniapps/assistant/src/memory/memory'\n")
        self.write("training/dump.py", "rows = store.exportAll()\n")
        ps = self.problems()
        self.assertEqual(len(ps), 2)
        self.assertTrue(any("memory store" in p for p in ps))
        self.assertTrue(any("memory export" in p for p in ps))

    def test_node_modules_are_not_ours(self):
        self.write("miniapps/assistant/node_modules/trl/index.js", "SFTTrainer\n")
        self.assertEqual(self.problems(), [])


if __name__ == "__main__":
    unittest.main()
